    (v_chapter, 'mcq', 'concept', 'bank', 3, 'If the velocity of a body is uniform then its acceleration will be:', '["Positive","Negative","Zero","Doubled"]'::jsonb, 'C', 1),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A passenger train traveling eastward along a straight track begins to slow down as it approaches a station. The direction of the train''s acceleration is:', '["Toward the East","Toward the West","Vertically downward","It has no direction because it is slowing down"]'::jsonb, 'B', 1),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'An airplane is flying toward the Southeast when the pilot throttles back the engines, causing the plane to slow down. The direction of the aircraft''s acceleration is toward the:', '["Southeast","Northwest","Southwest","Northeast"]'::jsonb, 'B', 1),
