    (v_chapter, 'mcq', 'concept', 'bank', 3, 'A speed-time graph features a straight line sloping downward toward the right. This represents:', '["Uniform acceleration","Uniform deceleration","Non-uniform acceleration","Constant speed"]'::jsonb, 'B', 1),
    (v_chapter, 'mcq', 'concept', 'bank', 3, 'When a distance-time graph shows a curved line that bends gradually upward (getting steeper), the motion of the body can be described as:', '["Uniform speed","Constant velocity","Non-uniform speed where the object is speeding up","Non-uniform speed where the object is slowing down"]'::jsonb, 'C', 1),
